# src/mapper.py# --- Fuzzy mapper (kept as fallback) ---from rapidfuzz import fuzzALIASES = {    "tensile_strength": ["uts","ultimate_tensile_strength","tensile_strength_mpa","σ_uts","tensile strength"],    "elongation_at_break": ["elong%","elongation","eab","elongation_at_break_%","elongation at break"],    "modulus": ["youngs_modulus","e_modulus","modulus_gpa","young's modulus","E"],    "specimen_type": ["specimen","sample_type","type"],    "test_speed_mm_per_min": ["speed","crosshead_speed","mm_min","test_speed"],    "lot": ["lot","batch_id","lot_id"]}def suggest_mapping_fuzzy(headers, required_metrics):    mapping = {}    for m in required_metrics:        best_h, best_s = None, -1        for h in headers:            scores = [fuzz.WRatio(h, m)] + [fuzz.WRatio(h, a) for a in ALIASES.get(m, [])]            s = max(scores)            if s > best_s:                best_h, best_s = h, s        mapping[m] = best_h    return mapping# --- LLM mapper (new) ---import os, requests, jsonOPENAI_API_KEY = os.environ.get("OPENAI_API_KEY")OPENAI_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")def suggest_mapping_llm(headers, required_metrics):    """    Ask an LLM to map CSV headers to required metrics.    Returns a dict like: {"mapping": {...}, "notes": "why choices were made"}    or None if the LLM call fails.    """    if not OPENAI_API_KEY:        return None    system = "Map CSV headers to canonical metrics. Return JSON only. If unsure, choose the closest header."    user = f"""Required metrics: {required_metrics}Available headers: {headers}Return JSON exactly like:{{"mapping": {{"metric_name":"best_header_or_empty_string", ...}}, "notes":"one short sentence"}}"""    try:        r = requests.post(            "https://api.openai.com/v1/chat/completions",            headers={"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"},            json={                "model": OPENAI_MODEL,                "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],                "temperature": 0.1,                "max_tokens": 250            },            timeout=60        )        if r.status_code != 200:            return None        txt = r.json()["choices"][0]["message"]["content"].strip()        obj = json.loads(txt)        # minimal shape validation        if not isinstance(obj, dict) or "mapping" not in obj:            return None        return obj    except Exception:        return None